109	//===----------------------------------------------------------------------===//
110	// tilesim-style micro-architecture tables (migrated from tilesim 910B1)
111	//===----------------------------------------------------------------------===//
112	
113	/// One row of the per-(intrinsic, dtype) vector instruction cycle table.
114	/// Mirrors tilesim VecIntrinsics: computing/head/interval cycles per repeat.
115	struct VecCycleEntry {
116	  int compute = 0;
117	  int head = 0;
118	  int interval = 0;
119	};
120	
121	/// Small-packet bandwidth fitting coefficients (tilesim pkt_param).
122	/// Applied when the transfer packet size is below ``thresholdBytes``.
123	struct SmallPacketCoeffs {
124	  bool enabled = false;
125	  int thresholdBytes = 256;
126	  // Bucket selection mirrors tilesim: <64B -> "64B", <128B -> "128B",
127	  // <256B -> "256B". Each bucket has (a, b) fitting coefficients.
128	  double a64 = 0, b64 = 0;
129	  double a128 = 0, b128 = 0;
130	  double a256 = 0, b256 = 0;
131	};
132	
133	/// A bandwidth entry keyed by "src:dst" memory spaces.
134	/// Either core-independent (singleGbps) or per-core (degrades as more cores
135	/// contend for the same off-chip port, e.g. GM<->UB on 910B).
136	struct BandwidthTable {
137	  bool hasPerCore = false;
138	  double singleGbps = 0.0;           // core-independent bandwidth (GB/s)
139	  std::map<int, double> perCoreGbps; // core_num -> GB/s (1..N)
140	  SmallPacketCoeffs smallPacket;
141	};
142	
143	/// Cube (GEMM) micro-architecture parameters migrated from tilesim
144	/// (cube_throughput, cube_repeat_cycles, L0 tile limit for best_k0).
145	struct CubeModelConfig {
146	  // basic throughput per repeat: [basicM, basicK, basicN].
147	  // tilesim stores cube_throughput as [16, 32, 16]; the K value is a
148	  // numerator divided by the element byte size, i.e. basicK = 32/elemBytes
149	  // (fp16->16, fp32->8, int8->32), which equals the fractal K dimension.
150	  int basicM = 16;
151	  int basicKNumerator = 32; // basicK = basicKNumerator / (elemBytes)
152	  int basicN = 16;
153	  // repeat cycles per dtype key ("fp32","fp16","bf16","int8")
154	  llvm::StringMap<int> repeatCycles;
155	  // L0 tile footprint limit (bytes) controlling best_k0 selection.
156	  int l0TileLimitKb = 32;
157	};
