360	  // l0c/ub). Vector instruction cycles keyed by intrinsic -> dtype -> entry.
361	  llvm::StringMap<BandwidthTable> bandwidthTables;
362	  llvm::StringMap<llvm::StringMap<VecCycleEntry>> vecCycleTables;
363	  CubeModelConfig cubeModel;
