365	  bool enableSmallPacketBw = false;
366	  // Global small-packet coefficients (tilesim pkt_param): a single (a,b) set
367	  // per size bucket applied to ANY mover lookup when enableSmallPacketBw is on
368	  // and the mover's own table has no per-table small_packet entry. tilesim
369	  // keeps one global pkt_param dict on ArcConfig (910B1.yaml); per-table
370	  // overrides it.
371	  SmallPacketCoeffs globalSmallPacket;
372	  bool hasGlobalSmallPacket = false;
373	  // Mutex unit groups (tilesim MutexComponents): each group is a clique of
374	  // unit-name strings that share a pipeline and cannot run in parallel.
375	  // Default 910B: {"vec_mte2", "mte3"} (AIV MTE2<->MTE3).
376	  std::vector<std::vector<std::string>> mutexGroups;
377	};
