1	//===- EstimateCycles.cpp - Estimate execution cycles --------------------===//
2	//
3	// This file estimates execution cycles for AscendModel operations using
4	// the Roofline model. Compute and memory operations can overlap, so we
5	// take max(compute_time, memory_time) instead of sum.
6	//
7	// For Triton kernels with loops depending on tt.get_program_id, use:
8	//   inproc-costmodel --estimate-cycles="arg-bindings=arg2=100,pid_x=0"
9	//   input.mlir
10	//
11	//===----------------------------------------------------------------------===//
12	
13	#include "AscendModel/HardwareConfig.h"
14	#include "AscendModel/IR/AscendModelDialect.h"
15	#include "AscendModel/IR/AscendModelInterfaces.h"
16	#include "AscendModel/Transforms/Passes.h"
17	#include "AscendModel/Utils.h"
18	
19	#include "mlir/Dialect/Arith/IR/Arith.h"
20	#include "mlir/Dialect/SCF/IR/SCF.h"
21	#include "mlir/IR/BuiltinOps.h"
22	#include "mlir/Pass/Pass.h"
23	#include "llvm/Support/raw_ostream.h"
24	
25	namespace mlir {
26	namespace ascend {
27	
28	#define GEN_PASS_DEF_ESTIMATECYCLESPASS
29	#include "AscendModel/Transforms/Passes.h.inc"
30	
31	namespace {
32	
33	using utils::analyzeScfForTripCount;
34	using utils::getLoopMultiplier;
35	using utils::getNumElements;
36	using utils::getScfForTripCount;
37	using utils::getScfForTripCountWithBindings;
38	using utils::LoopTripCountResult;
39	using utils::parseBindings;
40	using utils::parseLoopTripCounts;
41	
42	//===----------------------------------------------------------------------===//
43	// Roofline Analysis
44	//===----------------------------------------------------------------------===//
45	
46	/// Statistics for roofline analysis, separated by hardware path.
47	struct RooflineStats {
48	  // Cube path
49	  int64_t cubeFlops = 0;
50	  int64_t cubeLoadBytes = 0;  // CubeMTE2
51	  int64_t cubeStoreBytes = 0; // FixPipe
52	
53	  // Vector path
54	  int64_t vectorFlops = 0;
55	  int64_t vectorLoadBytes = 0;  // VecMTE2
56	  int64_t vectorStoreBytes = 0; // MTE3
57	
58	  // Cycle estimates (per-op, for annotation)
59	  int64_t cubeCycles = 0;
60	  int64_t cubeLoadCycles = 0;
61	  int64_t cubeStoreCycles = 0;
62	  int64_t vectorCycles = 0;
63	  int64_t vectorLoadCycles = 0;
64	  int64_t vectorStoreCycles = 0;
65	
66	  /// Calculate total cycles using roofline model.
67	  /// For each path (Cube/Vector), take max of compute and memory time.
68	  /// Then consider if paths can overlap or must serialize.
69	  int64_t calculateRooflineCycles(const HardwareConfig &config,
70	                                  bool cubeVectorOverlap = true) const {
71	    // Cube path: max(compute, load, store)
72	    int64_t cubePathCycles =
73	        std::max({cubeCycles, cubeLoadCycles, cubeStoreCycles});
74	
75	    // Vector path: max(compute, load, store)
76	    int64_t vectorPathCycles =
77	        std::max({vectorCycles, vectorLoadCycles, vectorStoreCycles});
78	
79	    // If Cube and Vector can overlap, take max; otherwise sum
80	    if (cubeVectorOverlap) {
81	      return std::max(cubePathCycles, vectorPathCycles);
82	    } else {
83	      return cubePathCycles + vectorPathCycles;
84	    }
85	  }
86	};
87	
88	//===----------------------------------------------------------------------===//
89	// Pass Implementation
90	//===----------------------------------------------------------------------===//
91	
92	struct EstimateCyclesPass
93	    : public impl::EstimateCyclesPassBase<EstimateCyclesPass> {
94	  using EstimateCyclesPassBase::EstimateCyclesPassBase;
95	
96	  void runOnOperation() override {
97	    ModuleOp module = getOperation();
98	
99	    std::string hardwareConfigError;
100	    auto hardwareConfig =
101	        loadHardwareConfigForAnalysis(hardwareConfigPath, hardwareConfigError);
102	    if (!hardwareConfig) {
103	      emitError(module.getLoc(), hardwareConfigError);
104	      return signalPassFailure();
105	    }
106	    const HardwareConfig &config = *hardwareConfig;
107	
108	    // Parse bindings
109	    llvm::DenseMap<unsigned, int64_t> argBindings;
110	    llvm::StringMap<int64_t> programIdBindings;
111	    if (!argBindingsStr.empty()) {
112	      std::string parseError;
113	      if (!parseBindings(argBindingsStr, argBindings, programIdBindings,
114	                         parseError)) {
115	        emitError(module.getLoc(), parseError);
116	        return signalPassFailure();
117	      }
118	    }
119	
120	    // Parse loop trip count overrides
121	    SmallVector<int64_t> loopTripCountOverrides;
122	    if (!loopTripCountsStr.empty()) {
123	      std::string parseError;
124	      if (!parseLoopTripCounts(loopTripCountsStr, loopTripCountOverrides,
125	                               parseError)) {
126	        emitError(module.getLoc(), parseError);
127	        return signalPassFailure();
128	      }
129	    }
130	
131	    bool hasError = false;
132	
133	    // First pass: collect all loops and assign trip counts
134	    SmallVector<scf::ForOp> allLoops;
135	    module.walk([&](scf::ForOp forOp) { allLoops.push_back(forOp); });
136	
137	    for (size_t loopIdx = 0; loopIdx < allLoops.size(); ++loopIdx) {
138	      scf::ForOp forOp = allLoops[loopIdx];
139	      int64_t tripCount = 1;
140	      std::string source = "unknown";
141	
142	      if (loopIdx < loopTripCountOverrides.size()) {
143	        tripCount = loopTripCountOverrides[loopIdx];
144	        source = "override";
145	      } else {
146	        auto result = getScfForTripCountWithBindings(forOp, argBindings,
147	                                                     programIdBindings);
148	
149	        if (result.isStatic) {
150	          tripCount = result.staticTripCount;
151	          source = result.dependentArgs.empty() &&
152	                           result.lowerBound.dependentProgramIds.empty() &&
153	                           result.upperBound.dependentProgramIds.empty()
154	                       ? "static"
155	                       : "evaluated";
156	        } else if (!result.errorMsg.empty()) {
157	          std::string errorMsg = "Loop " + std::to_string(loopIdx) +
158	                                 " trip count cannot be determined.\n";
159	          errorMsg += "  Lower bound: " + result.lowerBound.description + "\n";
160	          errorMsg += "  Upper bound: " + result.upperBound.description + "\n";
161	          errorMsg += "  Step: " + result.step.description + "\n";
162	          errorMsg += result.errorMsg;
163	
164	          emitError(forOp.getLoc(), errorMsg);
165	          hasError = true;
166	          continue;
167	        }
168	      }
169	
170	      forOp->setAttr("ascend.trip_count",
171	                     IntegerAttr::get(IntegerType::get(forOp.getContext(), 64),
172	                                      tripCount));
173	      forOp->setAttr("ascend.trip_count_source",
174	                     StringAttr::get(forOp.getContext(), source));
175	    }
176	
177	    if (hasError)
178	      return signalPassFailure();
179	
180	    // Second pass: estimate cycles for each operation and collect roofline
181	    // stats
182	    RooflineStats stats;
183	    int64_t totalOps = 0;
184	
185	    module.walk([&](Operation *op) {
186	      if (isa<scf::ForOp, scf::YieldOp, scf::IfOp>(op))
187	        return;
188	
189	      if (auto cyclesOp = dyn_cast<EstimateCyclesOpInterface>(op)) {
190	        int64_t cycles = cyclesOp.estimateCycles(config);
191	        if (cycles <= 0)
192	          return;
193	
194	        HWUnit hwUnit = cyclesOp.getHWUnit();
195	        int64_t loopMultiplier = getLoopMultiplier(op);
196	        int64_t totalOpCycles = cycles * loopMultiplier;
197	
198	        // Set attributes on the operation
199	        op->setAttr(
200	            "estimated_cycles",
201	            IntegerAttr::get(IntegerType::get(op->getContext(), 64), cycles));
202	        op->setAttr("hw_unit",
203	                    StringAttr::get(op->getContext(), stringifyHWUnit(hwUnit)));
204	
205	        if (int64_t bytes = cyclesOp.getTransferBytes(); bytes > 0) {
206	          op->setAttr(
207	              "bytes",
208	              IntegerAttr::get(IntegerType::get(op->getContext(), 64), bytes));
209	        }
210	        if (int64_t flops = cyclesOp.getFlops(); flops > 0) {
211	          op->setAttr(
212	              "flops",
213	              IntegerAttr::get(IntegerType::get(op->getContext(), 64), flops));
214	        }
215	        if (loopMultiplier > 1) {
216	          op->setAttr("loop_multiplier",
217	                      IntegerAttr::get(IntegerType::get(op->getContext(), 64),
218	                                       loopMultiplier));
219	        }
220	
221	        totalOps++;
222	
223	        // Accumulate roofline stats by hardware unit
224	        int64_t bytes = cyclesOp.getTransferBytes() * loopMultiplier;
225	        int64_t flops = cyclesOp.getFlops() * loopMultiplier;
226	
227	        switch (hwUnit) {
228	        case HWUnit::Cube:
229	          stats.cubeFlops += flops;
230	          stats.cubeCycles += totalOpCycles;
231	          break;
232	        case HWUnit::CubeMTE2:
233	          stats.cubeLoadBytes += bytes;
234	          stats.cubeLoadCycles += totalOpCycles;
235	          break;
236	        case HWUnit::FixPipe:
237	          stats.cubeStoreBytes += bytes;
238	          stats.cubeStoreCycles += totalOpCycles;
239	          break;
240	        case HWUnit::Vector:
241	          stats.vectorFlops += flops;
242	          stats.vectorCycles += totalOpCycles;
243	          break;
244	        case HWUnit::VecMTE2:
245	          stats.vectorLoadBytes += bytes;
246	          stats.vectorLoadCycles += totalOpCycles;
247	          break;
248	        case HWUnit::MTE3:
249	          stats.vectorStoreBytes += bytes;
250	          stats.vectorStoreCycles += totalOpCycles;
251	          break;
252	        default:
253	          break;
254	        }
255	      }
256	    });
257	
258	    // Calculate roofline-based total cycles
259	    int64_t rooflineCycles = stats.calculateRooflineCycles(config, true);
260	
261	    // Also calculate simple sum for comparison
262	    int64_t simpleSumCycles = stats.cubeCycles + stats.cubeLoadCycles +
263	                              stats.cubeStoreCycles + stats.vectorCycles +
264	                              stats.vectorLoadCycles + stats.vectorStoreCycles;
265	
266	    // Third pass: annotate loops with body cycles
267	    module.walk([&](scf::ForOp forOp) {
268	      int64_t tripCount = 1;
269	      if (auto attr = forOp->getAttrOfType<IntegerAttr>("ascend.trip_count"))
270	        tripCount = attr.getInt();
271	
272	      int64_t bodyCycles = 0;
273	      int64_t bodyOps = 0;
274	      for (Operation &op : forOp.getBody()->getOperations()) {
275	        if (isa<scf::YieldOp>(&op))
276	          continue;
277	        if (auto nestedFor = dyn_cast<scf::ForOp>(&op)) {
278	          if (auto nestedTotal =
279	                  nestedFor->getAttrOfType<IntegerAttr>("ascend.total_cycles"))
280	            bodyCycles += nestedTotal.getInt();
281	        } else if (auto cyclesAttr =
282	                       op.getAttrOfType<IntegerAttr>("estimated_cycles")) {
283	          bodyCycles += cyclesAttr.getInt();
284	          bodyOps++;
285	        }
286	      }
287	
