      py::arg("mlir_text"), py::arg("extra_args") = std::vector<std::string>{});
#endif

  // Initialize ascend IR bindings (ascendnpu_ir_builder, scope/hivm dialects)
  init_ascend_ir(m.def_submodule("ir"));
